extracted_python_code:
recent_buy_transactions = Transactions.WHERE(
    (LOWER(transaction_type) == 'buy') & (DATEDIFF("days", date_time, DATETIME('now')) <= 10)
).CALCULATE(
    ticker_symbol=ticker.symbol
)

result = recent_buy_transactions.PARTITION(
    name="ticker_groups", by=(ticker_symbol)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    num_buy_transactions=COUNT(Transactions)
).TOP_K(2, by=num_buy_transactions.DESC())

customer_metrics = Broker.CALCULATE(
    start_of_current_month=DATETIME('now', 'start of month'),
    start_of_period=DATETIME('now', 'start of month', '-6 months')
).Customers.WHERE(
    (join_date >= start_of_period) & (join_date < start_of_current_month)
).CALCULATE(
    signup_month=JOIN_STRINGS('-', YEAR(join_date), LPAD(MONTH(join_date), 2, '0'))
).PARTITION(
    name='monthly_groups', by=signup_month
).CALCULATE(
    month=signup_month,
    PMCS=COUNT(Customers),
    PMAT=AVG(Customers.transactions_made.amount)
)

result = Broker.CALCULATE(
    customer_count=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

transactions_in_range = Transactions.WHERE(
    (date_time >= "2023-01-01") & (date_time <= "2023-03-31")
)
transaction_type_summary = transactions_in_range.PARTITION(
    name="transaction_groups", by=transaction_type
).CALCULATE(
    transaction_type=transaction_type,
    num_distinct_customers=NDISTINCT(Transactions.customer_id),
    avg_shares=AVG(Transactions.shares)
).TOP_K(
    3, by=num_distinct_customers.DESC()
)

distinct_ticker_ids = DailyPrices.WHERE(date >= "2023-04-01").PARTITION(name="unique_tickers", by=ticker_id).CALCULATE(
    ticker_id=ticker_id
)

transactions_in_last_30_days = Transactions.WHERE(
    DATEDIFF("days", date_time, DATETIME('now')) <= 30
).CALCULATE(
    customer_country=customer.country
)

top_countries_by_amount = transactions_in_last_30_days.PARTITION(
    name="countries", 
    by=(customer_country)
).CALCULATE(
    country=customer_country,
    num_transactions=COUNT(Transactions),
    total_transaction_amount=SUM(Transactions.amount)
).TOP_K(
    5, 
    by=total_transaction_amount.DESC()
)

result = Broker.CALCULATE(
    lowest_close_price=MIN(
        DailyPrices.WHERE(
            (ticker.symbol == 'VTI') & 
            (DATEDIFF("days", date, DATETIME('now')) <= 7)
        ).close
    )
)

result = Broker.CALCULATE(
    num_transactions=COUNT(
        Customers.WHERE(
            DATEDIFF("days", join_date, DATETIME("now")) <= 70
        ).transactions_made
    )
)

result = Customers.WHERE(
    HAS(transactions_made) == 1
).CALCULATE(
    customer_id=_id,
    join_date=join_date,
    first_transaction_date=MIN(transactions_made.date_time)
).CALCULATE(
    _id=customer_id,
    time_to_first_transaction=DATEDIFF("days", join_date, first_transaction_date)
)

average_sale_price_q1_2023 = Dealership.CALCULATE(
    asp_q1_2023=AVG(Sales.WHERE((YEAR(sale_date) == 2023) & (MONTH(sale_date) <= 3)).sale_price)
)

gpm_2023 = Dealership.CALCULATE(
    total_revenue_2023=SUM(Sales.WHERE(YEAR(sale_date) == 2023).sale_price),
    total_cost_2023=SUM(Sales.WHERE(YEAR(sale_date) == 2023).car.cost)
).CALCULATE(
    gpm=(total_revenue_2023 - total_cost_2023) / total_cost_2023 * 100.0
)

total_sales_count = Dealership.CALCULATE(
    TSC=COUNT(Sales.WHERE(DATEDIFF("days", sale_date, 'now') < 7))
)

distinct_customer_ids = Sales.PARTITION(name="customer_groups", by=(customer_id)).CALCULATE(
    customer_id=customer_id
)

distinct_salespersons_with_cash_payment = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(LOWER(payment_method) == 'cash')) == 1
).CALCULATE(
    salesperson_id=_id
)

shortest_employment_salesperson = Salespersons.WHERE(
    PRESENT(termination_date)
).CALCULATE(
    days_employed=DATEDIFF("days", hire_date, termination_date)
).TOP_K(
    1, by=days_employed.ASC()
).CALCULATE(
    salesperson_name=JOIN_STRINGS(" ", first_name, last_name),
    phone_number=phone,
    days_employed=days_employed
)

weekend_payments_to_utility_co = Dealership.CALCULATE(
    num_weekend_payments=COUNT(
        PaymentsMade.WHERE(
            (LOWER(vendor_name) == 'utility company') & 
            ISIN(DAYNAME(payment_date), ('Saturday', 'Sunday'))
        )
    )
)

cars_in_inventory = Dealership.CALCULATE(
    latest_snapshot_date=MAX(
        InventorySnapshots.WHERE(
            (YEAR(snapshot_date) == 2023) & (MONTH(snapshot_date) == 3)
        ).snapshot_date
    )
).InventorySnapshots.WHERE(
    (snapshot_date == latest_snapshot_date) & (is_in_inventory == True)
).car.CALCULATE(
    _id,
    make,
    model,
    year
)

ddd_calculation = DermTreatment.Drugs.CALCULATE(
    drug_name=drug_name,
    average_ddd=AVG(
        treatments_used_in.WHERE(
            PRESENT(end_dt)
        ).CALCULATE(
            treatment_duration=DATEDIFF("days", start_dt, end_dt)
        ).WHERE(
            treatment_duration > 0
        ).CALCULATE(
            ddd=tot_drug_amt / treatment_duration
        ).ddd
    )
)

result = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            ENDSWITH(LOWER(email), '@gmail.com') | ENDSWITH(LOWER(email), '@yahoo.com')
        )
    )
)

result = DermTreatment.CALCULATE(
    patient_count=COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (LOWER(diagnosis.diag_name) == LOWER('Psoriasis vulgaris')) &
                    (LOWER(drug.drug_type) == LOWER('Biologic'))
                )
            ) == 1
        )
    )
)

alice_recent_treatments = DermTreatment.CALCULATE(
    start_of_current_month=DATETIME('now', 'start of month'),
    start_of_period=DATETIME('now', 'start of month', '-6 months')
).CALCULATE(
    num_treatments=COUNT(
        Patients.WHERE(LOWER(first_name) == 'alice').treatments_received.WHERE(
            (start_dt >= start_of_period) & (start_dt < start_of_current_month)
        )
    )
)

result = DermTreatment.CALCULATE(
    start_of_current_month=DATETIME('now', 'start of month'),
    start_of_12_months_ago=DATETIME('now', 'start of month', '-12 months')
).Treatments.WHERE(
    (start_dt >= start_of_12_months_ago) & (start_dt < start_of_current_month)
).CALCULATE(
    treatment_month=DATETIME(start_dt, 'start of month')
).PARTITION(name="monthly_groups", by=(treatment_month)).CALCULATE(
    month=treatment_month,
    PMTC=COUNT(Treatments),
    PMPD=NDISTINCT(Treatments.CALCULATE(patient_diag_key=JOIN_STRINGS('-', patient_id, diag_id)).patient_diag_key)
).ORDER_BY(month.ASC())

result = DermTreatment.CALCULATE(
    avg_weight=AVG(Drugs.WHERE(LOWER(drug_name) == 'drugalin').treatments_used_in.patient.weight_kg)
)

caw_male_patients = DermTreatment.CALCULATE(
    caw=AVG(Patients.WHERE(LOWER(gender) == 'male').weight_kg)
)

npi_by_year = DermTreatment.Patients.CALCULATE(
    first_treatment_year=YEAR(MIN(treatments_received.start_dt))
).PARTITION(
    name="yearly_groups", by=first_treatment_year
).CALCULATE(
    year=first_treatment_year,
    num_new_patients=COUNT(Patients)
).ORDER_BY(year.ASC()).CALCULATE(
    year=year,
    num_new_patients=num_new_patients,
    NPINPI=num_new_patients - PREV(num_new_patients, by=year.ASC(), default=0)
)

result = DermTreatment.CALCULATE(
    PIC=COUNT(Patients.WHERE((LOWER(gender) == 'female') & (LOWER(ins_type) == 'private')))
)

doctor_states_for_biologics = Doctors.WHERE(
    HAS(prescribed_treatments.WHERE(LOWER(drug.drug_type) == 'biologic')) == 1
).PARTITION(
    name="states", by=loc_state
).CALCULATE(
    state=loc_state
)

recent_psoriasis_treatments = DermTreatment.CALCULATE(
    treatment_count=COUNT(
        Treatments.WHERE(
            LIKE(LOWER(diagnosis.diag_name), '%psoriasis%') &
            PRESENT(drug.fda_appr_dt) &
            PRESENT(end_dt) &
            (DATEDIFF("months", end_dt, DATETIME('now')) <= 6)
        )
    )
)

avg_age_of_patients = DermTreatment.CALCULATE(
    avg_patient_age=AVG(
        Patients.WHERE(
            (LOWER(gender) == 'male') & (LOWER(ins_type) == 'private')
        ).CALCULATE(
            age_in_years=DATEDIFF("years", date_of_birth, DATETIME('now'))
        ).age_in_years
    )
)

result = Merchants.CALCULATE(
    merchant_name=name,
    cpur=NDISTINCT(
        transactions_received.WHERE(
            LOWER(status) == LOWER("successful")
        ).WHERE(
            PRESENT(coupon_id)
        ).coupon_id
    ) / NDISTINCT(
        transactions_received.WHERE(
            LOWER(status) == LOWER("successful")
        ).txid
    )
)

result = Ewallet.CALCULATE(
    num_transactions=COUNT(
        Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
            DATEDIFF("days", created_at, DATETIME('now')) <= 7
        )
    ),
    total_amount=SUM(
        Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
            DATEDIFF("days", created_at, DATETIME('now')) <= 7
        ).amount
    )
)

lub_per_user = Users.CALCULATE(
    user_id=uid,
    latest_user_balance=balances.WHERE(
        RANKING(by=updated_at.DESC(), per="Users") == 1
    ).SINGULAR().balance
)

result = Users.CALCULATE(
    user_id=uid,
    marketing_opt_in=setting_snapshots.WHERE(
        RANKING(by=snapshot_date.DESC(), per="Users") == 1
    ).SINGULAR().marketing_opt_in
)

user_session_durations = Users.CALCULATE(
    user_id=uid,
    total_duration=ROUND(SUM(
        sessions.WHERE(
            (session_start_ts >= '2023-06-01') & (session_start_ts < '2023-06-08')
        ).CALCULATE(
            duration_in_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration_in_seconds
    ), 0)
).WHERE(
    total_duration > 0
).ORDER_BY(
    total_duration.DESC()
)

tuc_result = Ewallet.CALCULATE(
    tuc_count=COUNT(UserSessions.WHERE(session_start_ts >= DATETIME('now', '-1 month')))
)

distinct_transaction_notification_users = Notifications.WHERE(
    LOWER(notification_type) == 'transaction'
).PARTITION(
    name='distinct_users', by=user_id
).CALCULATE(
    user_id
)

result = Merchants.WHERE(
    HAS(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150)
    )) == 1
).CALCULATE(
    merchant_name=name,
    total_transactions=COUNT(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150)
    )),
    total_amount=SUM(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150)
    ).amount)
).TOP_K(2, by=total_amount.DESC())

result = Ewallet.CALCULATE(
    median_merchant_balance=MEDIAN(
        Merchants.WHERE(
            (LOWER(status) == 'active') & 
            (CONTAINS(LOWER(category), 'retail'))
        ).balances.WHERE(
            updated_at >= DATETIME('now', 'start of day')
        ).balance
    )
)

# Find the earliest snapshot date in 2023
earliest_2023_snapshot = UserSettingSnapshots.WHERE(
    YEAR(snapshot_date) == 2023
).TOP_K(1, by=snapshot_date.ASC())

# Calculate the average limits for that earliest date
result = Ewallet.CALCULATE(
    avg_daily_limit=AVG(
        UserSettingSnapshots.WHERE(
            snapshot_date == earliest_2023_snapshot.SINGULAR().snapshot_date
        ).tx_limit_daily
    ),
    avg_monthly_limit=AVG(
        UserSettingSnapshots.WHERE(
            snapshot_date == earliest_2023_snapshot.SINGULAR().snapshot_date
        ).tx_limit_monthly
    )
)

result = Users.WHERE(
    HASNOT(
        notifications.WHERE(
            DATEDIFF("days", user.created_at, created_at) <= 365
        )
    ) == 1
).CALCULATE(
    user_name=username,
    user_email=email,
    signup_date=created_at
)
